#include <iostream>
#include <algorithm>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll gcd(ll a, ll b) {
    return b == 0 ? a : gcd(b, a % b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, a, b;
    cin >> l >> a >> b;

    ll g = gcd(a, b);
    i128 m = static_cast<i128>(a / g) * b;
    ll limit = min(a, b);

    i128 ans = (static_cast<i128>(l) / m) * limit;
    ll remainder = static_cast<ll>(static_cast<i128>(l) % m);
    ans += min(remainder, limit - 1);

    cout << static_cast<ll>(ans);
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll gcd_ll(ll a, ll b) {
    return b == 0 ? a : gcd_ll(b, a % b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll l, a, b;
    cin >> l >> a >> b;

    ll g = gcd_ll(a, b);
    i128 m = static_cast<i128>(a / g) * b;
    ll ans = 0;

    if (m <= l) {
        ll lcm = static_cast<ll>(m);
        ans += (l / lcm) * min(a, b);
        l %= lcm;
    }

    ans += min(l, min(a - 1, b - 1));
    cout << ans;

    return 0;
}

